UPDATE "User" SET "image" = '/api/images/media/3cf2ada1-59d8-3377-0101-3161f401e096.png' WHERE "image" = 'https://www.kindpng.com/picc/m/24-248253_user-profile-default-image-png-clipart-png-download.png';
-- Older clients omit image and use the historical SQLite default. Normalize it
-- without rebuilding User and its foreign keys. New Prisma clients use R2 directly.
CREATE TRIGGER IF NOT EXISTS "User_r2_default_image" AFTER INSERT ON "User"
WHEN NEW."image" = 'https://www.kindpng.com/picc/m/24-248253_user-profile-default-image-png-clipart-png-download.png'
BEGIN
  UPDATE "User" SET "image" = '/api/images/media/3cf2ada1-59d8-3377-0101-3161f401e096.png' WHERE "id" = NEW."id";
END;
